#!/usr/bin/env node

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { resolve } from "node:path";

const GENERATED_NOTICE = `/*
  GENERATED by scripts/sync-design-bundle.mjs.
  Do not edit this file by hand. The implementation source of truth is
  src/styles/global.css plus src/styles/themes/*.css.
*/`;

function extractRule(source, selector) {
  const start = source.indexOf(`${selector} {`);
  if (start === -1) throw new Error(`Could not find ${selector} in the colour source.`);

  const open = source.indexOf("{", start);
  let depth = 0;
  for (let index = open; index < source.length; index += 1) {
    if (source[index] === "{") depth += 1;
    if (source[index] === "}") depth -= 1;
    if (depth === 0) return source.slice(start, index + 1).trim();
  }

  throw new Error(`Could not find the closing brace for ${selector}.`);
}

function properties(rule) {
  return new Map(
    [...rule.matchAll(/^\s*(--[a-z0-9-]+):\s*([^;]+);/gim)].map((match) => [
      match[1],
      match[2].trim(),
    ]),
  );
}

function escapeHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function tokenName(name) {
  return name.slice(2);
}

function buildPreview(rootRule, darkRule) {
  const root = properties(rootRule);
  const dark = properties(darkRule);
  const primitives = [...root].filter(([, value]) => /^#[0-9a-f]{6}$/i.test(value));
  const semantics = [...root].filter(([, value]) => value.startsWith("var("));

  const families = new Map();
  for (const [name, value] of primitives) {
    const [, family, step] = name.match(/^--([a-z]+)-(.+)$/) ?? [];
    if (!family) continue;
    const entries = families.get(family) ?? [];
    entries.push({ name, step, value });
    families.set(family, entries);
  }

  const primitiveHtml = [...families]
    .map(([family, entries]) => `
      <section class="family">
        <h3>${escapeHtml(family)}</h3>
        <div class="swatch-grid">
          ${entries.map(({ name, step, value }) => `
            <article class="primitive">
              <div class="chip" style="background:var(${name})"></div>
              <strong>${escapeHtml(step)}</strong>
              <code>${escapeHtml(value)}</code>
            </article>`).join("")}
        </div>
      </section>`)
    .join("");

  const semanticHtml = semantics
    .map(([name, lightValue]) => {
      const darkValue = dark.get(name) ?? lightValue;
      return `
        <article class="semantic">
          <code>${escapeHtml(name)}</code>
          <div class="semantic__pair">
            <div>
              <span class="semantic__chip" style="background:var(${name})"></span>
              <small>Light · ${escapeHtml(lightValue)}</small>
            </div>
            <div class="dark">
              <span class="semantic__chip" style="background:var(${name})"></span>
              <small>Dark · ${escapeHtml(darkValue)}</small>
            </div>
          </div>
        </article>`;
    })
    .join("");

  return `<!-- @dsCard group="Colours" -->
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Colour Tokens — Anuj Prajapati</title>
<style>
  @import "./tokens.css";
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 32px;
    background: var(--background-primary);
    color: var(--text-primary);
    font-family: ui-sans-serif, system-ui, sans-serif;
  }
  h1, h2, h3, p { margin-block-start: 0; }
  h1 { margin-block-end: 4px; font-size: 24px; }
  h2 { margin-block: 40px 16px; font-size: 18px; }
  h3 { margin-block-end: 10px; font-size: 14px; text-transform: capitalize; }
  p { max-width: 70ch; color: var(--text-secondary); }
  code { font-family: ui-monospace, "SFMono-Regular", Menlo, monospace; font-size: 11px; }
  .family + .family { margin-block-start: 24px; }
  .swatch-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(92px, 1fr)); gap: 10px; }
  .primitive, .semantic { min-width: 0; border: 1px solid var(--border-primary); background: var(--background-elevated); }
  .primitive { padding: 8px; }
  .primitive strong, .primitive code { display: block; }
  .chip { height: 52px; margin-block-end: 8px; border: 1px solid var(--border-tertiary); }
  .semantic-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 10px; }
  .semantic { padding: 12px; }
  .semantic > code { display: block; margin-block-end: 10px; overflow-wrap: anywhere; }
  .semantic__pair { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  .semantic__pair > div { min-width: 0; }
  .semantic__chip { display: block; height: 40px; margin-block-end: 5px; border: 1px solid var(--border-tertiary); }
  .semantic small { display: block; color: var(--text-secondary); font-size: 9px; overflow-wrap: anywhere; }
  .note { padding: 16px; border: 1px solid var(--border-primary); background: var(--background-elevated); }
</style>
</head>
<body>
  <h1>Colour tokens</h1>
  <p>Generated from the portfolio's ${primitives.length} primitives, canonical light/dark semantics, compatibility aliases, and Blue/Sage page-palette remaps.</p>

  <h2>Primitives</h2>
  ${primitiveHtml}

  <h2>Semantic tokens — light / dark</h2>
  <div class="semantic-grid">${semanticHtml}</div>

  <h2>Page palettes</h2>
  <p class="note"><code>data-palette="blue"</code> and <code>data-palette="sage"</code> remaps are included in <code>tokens.css</code>. Appearance remains independent through the <code>.dark</code> class.</p>
</body>
</html>
`.replace(/[ \t]+$/gm, "");
}

export function generatedDesignBundle(projectRoot = process.cwd()) {
  const globalCss = readFileSync(resolve(projectRoot, "src/styles/global.css"), "utf8");
  const blueCss = readFileSync(resolve(projectRoot, "src/styles/themes/blue.css"), "utf8").trim();
  const sageCss = readFileSync(resolve(projectRoot, "src/styles/themes/sage.css"), "utf8").trim();
  const rootRule = extractRule(globalCss, ":root");
  const darkRule = extractRule(globalCss, ".dark");

  return {
    "ds-bundle/tokens/tokens.css": `${GENERATED_NOTICE}\n\n${rootRule}\n\n${darkRule}\n\n${blueCss}\n\n${sageCss}\n`,
    "ds-bundle/tokens/colours.html": buildPreview(rootRule, darkRule),
  };
}

export function designBundleDrift(projectRoot = process.cwd()) {
  const generated = generatedDesignBundle(projectRoot);
  return Object.entries(generated)
    .filter(([file, expected]) => readFileSync(resolve(projectRoot, file), "utf8") !== expected)
    .map(([file]) => file);
}

export function writeDesignBundle(projectRoot = process.cwd()) {
  for (const [file, contents] of Object.entries(generatedDesignBundle(projectRoot))) {
    writeFileSync(resolve(projectRoot, file), contents);
  }
}

const isDirectRun = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isDirectRun) {
  if (process.argv.includes("--check")) {
    const drift = designBundleDrift();
    if (drift.length) {
      console.error(`✗ design bundle drift: ${drift.join(", ")}`);
      process.exit(1);
    }
    console.log("✓ design bundle matches the canonical colour sources");
  } else {
    writeDesignBundle();
    console.log("✓ regenerated ds-bundle colour tokens and preview");
  }
}
